.ds-button {
  --_btn-h: var(--sui-control-h-md);
  --_btn-px: var(--sui-control-px-md);
  --_btn-color: var(--sui-color-primary);
  --_btn-contrast: var(--sui-color-primary-contrast);
  --_btn-action: var(--_btn-color);
  --_btn-action-contrast: var(--_btn-contrast);

  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sui-space-2);
  min-height: var(--_btn-h);
  padding: var(--sui-space-1) var(--_btn-px);
  font-family: var(--sui-font);
  font-size: var(--sui-fs-button);
  font-weight: 500;
  line-height: 1.35;
  border: 1px solid transparent;
  border-radius: calc(var(--sui-radius) * 1.25);
  cursor: pointer;
  user-select: none;
  text-decoration: none;
  color: var(--_btn-color);
  background: transparent;
  transition: background var(--sui-transition), border-color var(--sui-transition),
              color var(--sui-transition), box-shadow var(--sui-transition);
  -webkit-tap-highlight-color: transparent;
}
.ds-button:focus-visible {
  outline: 2px solid var(--_btn-color);
  outline-offset: 2px;
}
.ds-button:is(:disabled,[aria-disabled="true"]) {
  cursor: not-allowed;
  opacity: .55;
  box-shadow: none;
}
.ds-button--color-primary   {
  --_btn-color: var(--sui-color-primary);
  --_btn-contrast: var(--sui-color-primary-contrast);
  --_btn-action: var(--sui-color-primary-action, var(--sui-color-primary));
  --_btn-action-contrast: var(--sui-color-primary-action-contrast, var(--sui-color-primary-contrast));
}
.ds-button--filled {
  background: linear-gradient(#0000, #0001) var(--_btn-action);
  color: var(--_btn-action-contrast);
  border-color: color-mix(in srgb,var(--_btn-action) 90%,var(--_btn-action-contrast));
  box-shadow: var(--sui-shadow-1);
}
.ds-button--filled:not(:disabled,[aria-disabled="true"]):hover {
  background-color: color-mix(in srgb,var(--_btn-action) 94%,black);
}
.ds-button--filled:not(:disabled,[aria-disabled="true"]):active {
  background-color: color-mix(in srgb,var(--_btn-action) 88%,black);
}

@media(pointer:coarse),(max-width:599.98px){.ds-button{min-height:max(var(--_btn-h),44px)}.ds-button--icon{width:max(var(--_btn-h),44px)}}@media(prefers-reduced-motion:reduce){.ds-button{transition:none}}

